1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.mapper.Locality;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
9	
10	/**
11	 * Validates the create-owner {@code postcode} against the owner's city. The postcode is
12	 * optional: a request without one is accepted unchanged (the contract stays
13	 * backward-compatible). When present it has already passed the {@code ^[0-9]{4}$} bean
14	 * validation (so a malformed value is a 400 before this step). For a city whose region is
15	 * known (see {@link Locality}) the four digits must fall within that region's inclusive
16	 * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); an out-of-range value raises
17	 * {@link InvalidPostcodeException} (400). A city with no known region accepts any 4-digit
18	 * postcode.
19	 */
20	public class ValidatePostcode {
21	
22	    /** Region -> inclusive 4-digit postcode range {low, high}. */
23	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
24	            "NSW", new int[] {2000, 2099},
25	            "VIC", new int[] {3000, 3099},
26	            "QLD", new int[] {4000, 4099});
27	
28	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
29	        String postcode = request.getPostcode();
30	        if (postcode == null || postcode.isBlank()) {
31	            return; // optional when absent
32	        }
33	        int[] range = REGION_POSTCODES.get(Locality.of(request.getCity()));
34	        if (range == null) {
35	            return; // city with no known region accepts any 4-digit postcode
36	        }
37	        int value = Integer.parseInt(postcode);
38	        if (value < range[0] || value > range[1]) {
39	            throw new InvalidPostcodeException(postcode, request.getCity());
40	        }
41	    }
42	}
