3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Normalizes the create-owner telephone into E.164 form and writes it back onto the body so
9	 * {@link BuildOwner} maps and {@link SaveOwner} stores the canonical value. A leading '+'
10	 * and country code are kept when present; otherwise country code '+61' is assumed and a
11	 * single leading '0' is dropped from the national digits. Spaces, dashes and brackets are
12	 * stripped. A number that cannot form a valid E.164 string (8 to 15 digits after the '+')
13	 * raises {@link InvalidTelephoneException} (400).
14	 *
15	 * <p>Runs after {@link ValidateOwnerFields} (which rejects a blank telephone) and mutates the
16	 * validated body in place — {@code @Val} yields the same object the earlier step published.
17	 */
18	public class NormalizeOwnerTelephone {
19	
20	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
21	        String e164 = TelephoneE164.toE164(request.getTelephone());
22	        if (!TelephoneE164.isValid(e164)) {
23	            throw new InvalidTelephoneException(e164 == null ? "" : e164);
24	        }
25	        request.setTelephone(e164);
26	    }
27	}
