3	import java.util.Locale;
4	import java.util.regex.Pattern;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
9	
10	/**
11	 * Normalizes the owner {@code email}: it is optional, so a null or blank value is left
12	 * absent. When present it must be a syntactically valid address; otherwise
13	 * {@link InvalidEmailException} (400) is raised. A valid address is stored lower-cased on
14	 * the body so {@link BuildOwner}/{@link ApplyOwner} map and {@link SaveOwner} stores the
15	 * canonical form, and {@code GET} returns it lower-cased.
16	 *
17	 * <p>Mutates the validated body in place — {@code @Val} yields the same object the earlier
18	 * step published.
19	 */
20	public class NormalizeOwnerEmail {
21	
22	    /** Requires a non-empty local part, an {@code @}, and a domain containing a dot,
23	     *  with no whitespace or extra {@code @}. Rejects values like {@code "not-an-email"}. */
24	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
25	
26	    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
27	        String email = request.getEmail();
28	        if (email == null || email.isBlank()) {
29	            request.setEmail(null);
30	            return;
31	        }
32	        if (!EMAIL.matcher(email).matches()) {
33	            throw new InvalidEmailException(email);
34	        }
35	        request.setEmail(email.toLowerCase(Locale.ROOT));
36	    }
37	}
