11	/**
12	 * Rejects a create-owner request once {@link #DAILY_LIMIT} or more owners have already been
13	 * registered on this request's adjusted business day, comparing each stored owner's
14	 * {@code registrationDate} against the effective registration date (supplied or defaulted to
15	 * today, rolled forward off any weekend). Runs before {@link SaveOwner} so the request itself is
16	 * not counted. On reaching the limit raises {@link DailyOwnerLimitException} (429).
17	 */
18	public class CheckOwnerDailyLimit {
19	
20	    /** Maximum number of owners permitted to be created in a single day; the request is
21	     *  rejected at this count. */
22	    public static final int DAILY_LIMIT = 100;
23	
24	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
25	            throws DailyOwnerLimitException {
26	        LocalDate businessDay = BusinessDay.effective(request);
27	        int count = 0;
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (businessDay.equals(existing.getRegistrationDate())) {
30	                count++;
31	            }
32	        }
33	        if (count >= DAILY_LIMIT) {
34	            throw new DailyOwnerLimitException(count);
35	        }
36	    }
37	}
