7	/**
8	 * Records the owner's {@code namesakeCount}: the number of existing owners that, at the
9	 * moment this owner is created, already share the same first name and last name compared
10	 * case-insensitively (whitespace trimmed). Zero when the name is unique. Runs after
11	 * {@link BuildOwner} (so the entity, hence its names, exists) and before {@link SaveOwner}
12	 * (so the new owner is not counted among its own namesakes), and mutates the built
13	 * {@link Owner} in place.
14	 */
15	public class CountNamesakes {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        String firstName = normalize(owner.getFirstName());
19	        String lastName = normalize(owner.getLastName());
20	        int count = 0;
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (firstName.equals(normalize(existing.getFirstName()))
23	                    && lastName.equals(normalize(existing.getLastName()))) {
24	                count++;
25	            }
26	        }
27	        owner.setNamesakeCount(count);
28	    }
29	
30	    /** Lower-case and trim, treating null as empty, for case-insensitive comparison. */
31	    private static String normalize(String value) {
32	        return value == null ? "" : value.trim().toLowerCase();
33	    }
34	}
