1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code customerCode}, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}:
9	 * CITY3 is the upper-cased first three letters of the owner's city, LAST3 the upper-cased
10	 * first three letters of the owner's last name, and NNNN a per-city 4-digit zero-padded
11	 * sequence equal to one more than the number of owners already in that city (e.g.
12	 * {@code 'SYD-SMI-0007'}). Runs after {@link BuildOwner} (the entity, hence its city and
13	 * last name, exists) and before {@link SaveOwner} (so the new owner is not yet counted),
14	 * and mutates the built {@link Owner} in place.
15	 */
16	public class AssignCustomerCode {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        String city3 = prefix(owner.getCity());
20	        String last3 = prefix(owner.getLastName());
21	        String city = normalize(owner.getCity());
22	        int sequence = 1;
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (city.equals(normalize(existing.getCity()))) {
25	                sequence++;
26	            }
27	        }
28	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
29	    }
30	
31	    /** Upper-cased first three letters of the value. */
32	    private static String prefix(String value) {
33	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
34	    }
35	
36	    /** Lower-case and trim, treating null as empty, for case-insensitive city comparison. */
37	    private static String normalize(String value) {
38	        return value == null ? "" : value.trim().toLowerCase();
39	    }
40	}
