1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.ArrayList;
7	import java.util.List;
8	
9	import net.officefloor.plugin.variable.Val;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.repository.OwnerRepository;
12	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
13	
14	/**
15	 * Assigns a shared {@code householdId} when a create-owner request opts in with
16	 * {@code sharesHousehold=true} and there is an existing owner with the same last name and
17	 * address (the address compared in its normalized form via {@link AddressNormalizer} — the
18	 * the same normalized last-name-and-address rule). The identifier is <em>stable</em>: it is derived
19	 * deterministically from the normalized last name and address, so every housemate computes
20	 * the same value regardless of creation order. The value is set on the newly built
21	 * {@link Owner} and back-filled onto the existing housemate(s) so both carry it.
22	 *
23	 * <p>Runs after {@link BuildOwner} (so the entity exists) and before {@link SaveOwner}; when
24	 * the request does not opt in, or opts in but has no existing household to join, it is a no-op.
25	 */
26	public class AssignHousehold {
27	
28	    public void service(@Val OwnerFieldsDto request, @Val Owner built, OwnerRepository ownerRepository) {
29	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
30	            return;
31	        }
32	        String lastName = normalize(request.getLastName());
33	        String address = AddressNormalizer.normalize(request.getAddress());
34	        List<Owner> housemates = new ArrayList<>();
35	        for (Owner existing : ownerRepository.findAll()) {
36	            if (lastName.equals(normalize(existing.getLastName()))
37	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
38	                housemates.add(existing);
39	            }
40	        }
41	        if (housemates.isEmpty()) {
42	            return;
43	        }
44	        String householdId = householdId(lastName, address);
45	        built.setHouseholdId(householdId);
46	        for (Owner mate : housemates) {
47	            if (!householdId.equals(mate.getHouseholdId())) {
48	                mate.setHouseholdId(householdId);
49	                ownerRepository.save(mate);
50	            }
51	        }
52	    }
53	
54	    /** A stable household identifier: first 12 upper-case hex chars of SHA-256 over the
55	     *  normalized last name and address, so all housemates derive the same value. */
56	    private static String householdId(String lastName, String address) {
57	        try {
58	            byte[] digest = MessageDigest.getInstance("SHA-256")
59	                    .digest((lastName + "|" + address).getBytes(StandardCharsets.UTF_8));
60	            StringBuilder sb = new StringBuilder(digest.length * 2);
61	            for (byte b : digest) {
62	                sb.append(String.format("%02x", b));
63	            }
64	            return sb.substring(0, 12).toUpperCase();
65	        }
66	        catch (NoSuchAlgorithmException e) {
67	            throw new IllegalStateException("SHA-256 not available", e);
68	        }
69	    }
70	
71	    /** Lower-case, trim, and collapse internal whitespace runs to a single space. */
72	    private static String normalize(String value) {
73	        if (value == null) {
74	            return "";
75	        }
76	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
77	    }
78	}
