3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.mapper.IdentityKey;
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * Rejects a create-owner request whose derived {@code identityKey} exactly equals an existing
11	 * owner's. The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}
12	 * (see {@link IdentityKey}); this single rule now expresses what were previously the separate
13	 * telephone, email and household duplicate checks. Only a whole-key match is a duplicate — two
14	 * members of the same household (same householdId) with different telephones have different
15	 * keys and are both allowed.
16	 *
17	 * <p>Runs after {@link AssignHousehold} (so the built owner's householdId is settled) and
18	 * before {@link SaveOwner} (so the new owner is not yet among {@code findAll()}). On a match
19	 * raises {@link DuplicateIdentityException} (409).
20	 */
21	public class CheckOwnerIdentityUnique {
22	
23	    public void service(@Val Owner built, OwnerRepository ownerRepository)
24	            throws DuplicateIdentityException {
25	        String identityKey = IdentityKey.of(built);
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (identityKey.equals(IdentityKey.of(existing))) {
28	                throw new DuplicateIdentityException(identityKey);
29	            }
30	        }
31	    }
32	}
