3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Canonical form for an owner {@code address}, shared by every step that stores or compares
8	 * one. Normalization trims and collapses internal whitespace runs to a single space,
9	 * upper-cases, and expands common street-type abbreviations as whole words
10	 * ({@code ST}&rarr;{@code STREET}, {@code RD}&rarr;{@code ROAD}, {@code AVE}&rarr;{@code AVENUE}).
11	 * A {@code null} or whitespace-only value normalizes to the empty string.
12	 *
13	 * <p>The function is idempotent: normalizing an already-normalized address returns it
14	 * unchanged, so it is safe to apply again when comparing against stored owners.
15	 */
16	final class AddressNormalizer {
17	
18	    private static final Map<String, String> ABBREVIATIONS =
19	            Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
20	
21	    private AddressNormalizer() {
22	    }
23	
24	    static String normalize(String value) {
25	        if (value == null) {
26	            return "";
27	        }
28	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
29	        if (collapsed.isEmpty()) {
30	            return "";
31	        }
32	        String[] tokens = collapsed.split(" ");
33	        StringBuilder sb = new StringBuilder(collapsed.length());
34	        for (int i = 0; i < tokens.length; i++) {
35	            if (i > 0) {
36	                sb.append(' ');
37	            }
38	            String expanded = ABBREVIATIONS.get(tokens[i]);
39	            sb.append(expanded != null ? expanded : tokens[i]);
40	        }
41	        return sb.toString();
42	    }
43	}
