8	/**
9	 * Business-day rules for owner registration. A registration date must fall on a business day:
10	 * a Saturday or Sunday rolls forward to the next Monday. This applies to the effective
11	 * registration date, whether supplied in the request or defaulted to the server date.
12	 */
13	final class BusinessDay {
14	
15	    private BusinessDay() {
16	    }
17	
18	    /** Rolls a weekend date forward to the next Monday; a weekday is returned unchanged. */
19	    static LocalDate rollForward(LocalDate date) {
20	        DayOfWeek dow = date.getDayOfWeek();
21	        if (dow == DayOfWeek.SATURDAY) {
22	            return date.plusDays(2);
23	        }
24	        if (dow == DayOfWeek.SUNDAY) {
25	            return date.plusDays(1);
26	        }
27	        return date;
28	    }
29	
30	    /**
31	     * The adjusted effective registration date for a create request: the supplied date, or the
32	     * server date when omitted, rolled forward off any weekend.
33	     */
34	    static LocalDate effective(OwnerFieldsDto request) {
35	        LocalDate supplied = request.getRegistrationDate();
36	        return rollForward(supplied != null ? supplied : LocalDate.now());
37	    }
38	}
