3	/**
4	 * Converts a free-form telephone into E.164 form.
5	 *
6	 * <p>Rules: when a leading {@code '+'} is present the following digits are taken as the
7	 * country code plus national number as given; otherwise country code {@code '+61'} is
8	 * assumed and a single leading {@code '0'} is dropped from the national digits. Spaces,
9	 * dashes, brackets and any other non-digit characters are stripped. A valid result has
10	 * between 8 and 15 digits after the {@code '+'}.
11	 */
12	final class TelephoneE164 {
13	
14	    private TelephoneE164() {
15	    }
16	
17	    /**
18	     * Converts {@code raw} to its E.164 candidate string (a leading {@code '+'} followed
19	     * by digits), or {@code null} when it carries no digits at all. Length is not enforced
20	     * here — call {@link #isValid(String)} to check the 8..15 digit rule.
21	     */
22	    static String toE164(String raw) {
23	        if (raw == null) {
24	            return null;
25	        }
26	        String trimmed = raw.trim();
27	        boolean hasPlus = trimmed.startsWith("+");
28	        String digits = trimmed.replaceAll("\\D", "");
29	        if (digits.isEmpty()) {
30	            return null;
31	        }
32	        if (hasPlus) {
33	            return "+" + digits;
34	        }
35	        String national = digits.startsWith("0") ? digits.substring(1) : digits;
36	        return "+61" + national;
37	    }
38	
39	    /**
40	     * True when {@code e164} is a {@code '+'} followed by 8 to 15 digits and, for country
41	     * codes with a known fixed national-number length, the national number is exactly that
42	     * length: {@code '+61'} requires 9 national digits, {@code '+1'} requires 10.
43	     */
44	    static boolean isValid(String e164) {
45	        if (e164 == null || !e164.startsWith("+")) {
46	            return false;
47	        }
48	        String digits = e164.substring(1);
49	        if (digits.length() < 8 || digits.length() > 15) {
50	            return false;
51	        }
52	        if (digits.startsWith("61")) {
53	            return digits.length() - 2 == 9;
54	        }
55	        if (digits.startsWith("1")) {
56	            return digits.length() - 1 == 10;
57	        }
58	        return true;
59	    }
60	}
