37	    /** The canonical region for {@code city}, or "UNKNOWN" when it is not in the table. */
38	    public static String of(String city) {
39	        return city == null ? "UNKNOWN" : CITY_REGION.getOrDefault(city, "UNKNOWN");
40	    }
